import fs from 'node:fs';
import path from 'node:path';

const root = process.cwd();
const read = (file) => fs.readFileSync(path.join(root, file), 'utf8');
const checks = [];
const check = (name, condition, detail) => checks.push({ name, pass: Boolean(condition), detail });

const buyer = read('src/features/OwnershipPlatform/pages/BuyerPlatform.tsx');
const app = read('src/App.tsx');
const notificationContext = read('src/context/NotificationContext.tsx');
const dashboardHub = read('src/components/DashboardHub.tsx');
const chatHub = read('src/features/UnifiedCommunicationHub.tsx');
const favoriteRoutes = read('backend/routes/favoriteRoutes.js');
const favoriteController = read('backend/controllers/favoriteController.js');
const ownershipRoutes = read('backend/routes/ownershipRoutes.js');
const ownershipController = read('backend/controllers/ownershipController.js');
const loanRoutes = read('backend/routes/loanApplicationRoutes.js');
const loanController = read('backend/controllers/loanApplicationController.js');
const escrowRoutes = read('backend/routes/escrowRoutes.js');
const escrowController = read('backend/controllers/escrowController.js');
const inspectionRoutes = read('backend/inspection/routes/inspectionRoutes.js');
const inspectionLegacy = read('backend/inspection/controllers/legacyCompatibilityController.js');
const bookingService = read('backend/inspection/services/bookingService.js');
const notificationRoutes = read('backend/routes/notificationRoutes.js');
const notificationController = read('backend/controllers/notificationController.js');
const chatRoutes = read('backend/routes/chatRoutes.js');
const chatController = read('backend/controllers/chatController.js');

check('Buyer portal derives a stable account key from authenticated user id', /const userId = user\?\.id \? String\(user\.id\) : null/.test(buyer), 'Buyer workspace uses the authenticated identity rather than object identity.');
check('Buyer portal cancels stale account requests', /let cancelled = false/.test(buyer) && /return \(\) => \{ cancelled = true; \}/.test(buyer), 'Old account responses cannot commit after effect cleanup.');
check('Buyer portal masks data until the active account has loaded it', /dataSessionKey === userId/.test(buyer) && /visibleFavorites = sessionMatches \? favorites : \[\]/.test(buyer) && /visibleOwnedVehicles = sessionMatches \? ownedVehicles : \[\]/.test(buyer), 'Data is masked synchronously during account changes, before effects run.');
check('Buyer portal does not turn failed APIs into false empty lists', /Promise\.allSettled\(\[getFavorites\(\), getOwnershipDashboard\(\)\]\)/.test(buyer) && /unavailable data has not been treated as an empty list/.test(buyer), 'Independent API failures are surfaced with retry instead of silently becoming empty lists.');
check('Real owned vehicle response is rendered in My Garage', /visibleOwnedVehicles\.map/.test(buyer) && /Vehicles in your garage/.test(buyer), 'The existing ownership dashboard call is no longer fetched and discarded.');
check('Saved vehicle action opens the canonical saved-vehicle surface', /onClick=\{\(\) => onNavigate\?\.\('saved'\)\}/.test(buyer), 'Saved-vehicle cards route to saved inventory, not the generic marketplace.');
check('Private child workspaces are keyed by user identity', /ParticipantEscrowDesk key=\{user\.id\}/.test(buyer) && /finance-\$\{user\.id\}/.test(buyer) && /key=\{`\$\{user\.id\}-\$\{initialInspectionTab\}`\}/.test(buyer), 'Escrow, finance and inspection workspaces remount on account changes.');
check('Buyer portal is protected and signed-out prompt remains available', /'buyer-platform'/.test(app) && /navsWithOwnSignedOutPrompt = new Set\(\[[^\]]*'buyer-platform'/.test(app), 'The app retains the authenticated navigation boundary and local sign-in prompt.');
check('Buyer dashboard routes escrow deals to the private buyer workspace and exposes messages', /label:'My escrow deals',nav:'buyer-platform'/.test(dashboardHub) && /label:'Messages',nav:'chat'/.test(dashboardHub), 'Buyer shortcuts do not send participants to the public escrow explainer.');
check('Chat state masks prior-account conversations synchronously', /threadsOwnerId === currentUserId/.test(chatHub) && /setThreadsOwnerId\(null\)/.test(chatHub) && /currentUserIdRef\.current !== currentUserId/.test(chatHub), 'Conversation lists are hidden until owned by the current account and stale reads are ignored.');
check('Notification state masks prior-account rows synchronously', /dataSessionKey === sessionKey/.test(notificationContext) && /visibleNotifications = visibleSession \? notifications : \[\]/.test(notificationContext), 'Notification rows and counts are hidden unless their session key matches.');
check('Favorites routes require authentication', /router\.use\(protect\)/.test(favoriteRoutes), 'All favorite endpoints inherit authentication middleware.');
check('Favorite list query is scoped to caller', /Favorite\.find\(\{ user: req\.user\.id \}\)/.test(favoriteController) && /Favorite\.countDocuments\(\{ user: req\.user\.id \}\)/.test(favoriteController), 'List and total count are filtered by authenticated user id.');
check('Favorite mutations include caller in database predicate', /Favorite\.findOne\(\{ user: req\.user\.id, car: carId \}\)/.test(favoriteController) && /Favorite\.findOneAndDelete\(\{ user: req\.user\.id, car: carId \}\)/.test(favoriteController), 'Price alert and removal target the caller-owned favorite record.');
check('Ownership routes require authentication', /router\.get\('\/dashboard', protect/.test(ownershipRoutes) && /router\.get\('\/vehicles\/:vehicleId', protect/.test(ownershipRoutes), 'Buyer ownership routes require a verified session.');
check('Ownership controller delegates with authenticated owner id', /getOwnerDashboard\(req\.user\.id\)/.test(ownershipController) && /getVehicleDetails\(req\.user\.id, req\.params\.vehicleId\)/.test(ownershipController), 'Ownership services receive the caller identity independent of UI state.');
check('Financing buyer endpoints require authentication and admin review remains restricted', /router\.get\("\/my", protect/.test(loanRoutes) && /router\.get\("\/all", protect, adminOnly/.test(loanRoutes) && /router\.put\("\/:id\/status", protect, adminOnly/.test(loanRoutes), 'Buyer application listing is authenticated; cross-user review/listing APIs are admin-only.');
check('Financing application query is caller-scoped', /LoanApplication\.find\(\{ applicant: req\.user\.id \}\)/.test(loanController), 'GET /my filters by authenticated applicant.');
check('Escrow participant list filters by buyer or seller identity', /\$or: \[\{ buyer: req\.user\.id \}, \{ seller: req\.user\.id \}\]/.test(escrowController), 'Participant list is restricted to the authenticated buyer/seller.');
check('Escrow detail and state enforce participant/staff authorization', (escrowController.match(/canViewEscrow\(escrow, req\.user\)/g) || []).length >= 2, 'Single escrow and state endpoints enforce server-side visibility rules.');
check('Inspection customer routes require authentication', /router\.get\('\/my', requireAuth, legacy\.listMine\)/.test(inspectionRoutes) && /router\.get\('\/bookings', requireAuth, controller\.getCustomerBookings\)/.test(inspectionRoutes), 'Legacy buyer orders and canonical bookings are authenticated.');
check('Legacy inspection list is scoped to requester id', /from\('vehicle_inspections'\)\.select\('\*'\)\.eq\('requester_id', req\.user\.id\)/.test(inspectionLegacy), 'GET /my only returns the caller’s inspection orders.');
check('Inspection booking detail and cancellation enforce customer ownership', /String\(booking\.customer_id\) !== String\(actorId\)/.test(bookingService) && /String\(booking\.customer_id\) !== String\(userId\)/.test(bookingService), 'Booking reference lookup does not grant access by identifier alone.');
check('Notifications routes require authentication', /router\.use\(protect\)/.test(notificationRoutes), 'Notification reads and mutations inherit authentication.');
check('Notification reads and mutations are recipient-scoped', /filters: \{ user: req\.user\.id/.test(notificationController) && /String\(notification\.user\) !== String\(req\.user\.id\)/.test(notificationController) && /\{ id: req\.params\.id, user: req\.user\.id \}/.test(notificationController), 'Read/list/delete paths bind rows to the authenticated recipient.');
check('Chat routes require authentication', /router\.post\("\/", protect/.test(chatRoutes) && /router\.get\("\/:chatId\/messages", protect/.test(chatRoutes), 'Conversation APIs are not public.');
check('Chat message read/write and leave actions enforce participant membership', (chatController.match(/chat\.participants\.some\(\(p\) => String\(p\) === String\(req\.user\.id\)\)/g) || []).length >= 3 && /Only an actual participant may leave/.test(chatController), 'Message reads, sends and chat deletion are checked against participant membership.');
check('Private chat attachments require participant membership and no-store response', /!isParticipant \|\| !att/.test(chatController) && /"Cache-Control": "private, no-store"/.test(chatController), 'Attachment retrieval is membership-checked and marked non-cacheable.');
check('Canonical notifications route remains authenticated', /path === '\/notifications'\) return <RequireAuth><NotificationsPage \/><\/RequireAuth>/.test(app), 'Notification page entry point remains protected.');

const failures = checks.filter((c) => !c.pass);
for (const c of checks) console.log(`${c.pass ? 'PASS' : 'FAIL'} | ${c.name} | ${c.detail}`);
console.log(`\nBuyer portal boundary checks: ${checks.length - failures.length}/${checks.length} PASS`);
if (failures.length) process.exitCode = 1;
